/// @brief C++ wrappers for the `account` API.
/// @details Wraps: switch/services/acc.h.
namespace account {

/// NetworkServiceAccountId
using ::AccountNetworkServiceAccountId;
/// Profile
using ::AccountProfile;
/// ProfileBase
using ::AccountProfileBase;
using ::AccountServiceType;
/// Account UserId.
using ::AccountUid;
/// UserData
using ::AccountUserData;

/// Initialize account.
Result Initialize(AccountServiceType service_type);

/// Exit account.
void Exit(void);

/// Gets the Service object for the actual account service session.
Service* GetServiceSession(void);

/// Get the total number of user profiles.
Result GetUserCount(s32* user_count);

/**
 * @brief Get a list of all userIds. The returned list will never be larger than ACC_USER_LIST_SIZE.
 * @param uids Pointer to array of userIds.
 * @param max_uids Maximum number of userIds to return.
 * @param actual_total The actual total number of userIds found.
 */
Result ListAllUsers(AccountUid* uids, s32 max_uids, s32 *actual_total);

/// Get the userId for the last opened user.
Result GetLastOpenedUser(AccountUid *uid);

/// Get an AccountProfile for the specified userId.
Result GetProfile(AccountProfile* out, AccountUid uid);

/// IsUserRegistrationRequestPermitted
Result IsUserRegistrationRequestPermitted(bool *out);

/// TrySelectUserWithoutInteraction
Result TrySelectUserWithoutInteraction(AccountUid *uid, bool is_network_service_account_required);

/// Close the AccountProfile.
void ProfileClose(AccountProfile* profile);

/// Get \ref AccountUserData and \ref AccountProfileBase for the specified profile, userdata is optional (can be NULL).
Result ProfileGet(AccountProfile* profile, AccountUserData* userdata, AccountProfileBase* profilebase);

/// Get the icon image size.
Result ProfileGetImageSize(AccountProfile* profile, u32* image_size);

/// Load the JPEG profile icon, valid for both Miis and character icons. The output image_size is the same as the one from \ref accountProfileGetImageSize.
Result ProfileLoadImage(AccountProfile* profile, void* buf, size_t len, u32* image_size);

/// Gets the userId which was selected by the profile-selector applet (if any), prior to launching the currently running Application.
/// This gets the cached PreselectedUser loaded during accountInitialize, when PreselectedUser is available.
Result GetPreselectedUser(AccountUid *uid);

/**
 * @brief Checks whether the specified \ref AccountUid is valid/set (non-zero).
 * @param[in] Uid \ref AccountUid
 */
bool UidIsValid(const AccountUid *Uid);

} // namespace account

/// @brief C++ wrappers for the `aes128` API.
/// @details Wraps: switch/crypto/aes.h, switch/crypto/aes_cbc.h, switch/crypto/aes_ctr.h, switch/crypto/aes_xts.h.
namespace aes128 {

/// Context for AES-128 CBC.
using ::Aes128CbcContext;
/// Context for AES-128 operations.
using ::Aes128Context;
/// Context for AES-128 CTR.
using ::Aes128CtrContext;
/// Context for AES-128 XTS.
using ::Aes128XtsContext;
/// Context for AES-192 CBC.
using ::Aes192CbcContext;
/// Context for AES-192 operations.
using ::Aes192Context;
/// Context for AES-192 CTR.
using ::Aes192CtrContext;
/// Context for AES-192 XTS.
using ::Aes192XtsContext;
/// Context for AES-256 CBC.
using ::Aes256CbcContext;
/// Context for AES-256 operations.
using ::Aes256Context;
/// Context for AES-256 CTR.
using ::Aes256CtrContext;
/// Context for AES-256 XTS.
using ::Aes256XtsContext;

/// Initialize a 128-bit AES context.
void ContextCreate(Aes128Context *out, const void *key, bool is_encryptor);

/// Encrypt using an AES context (Requires is_encryptor when initializing)
void EncryptBlock(const Aes128Context *ctx, void *dst, const void *src);

/// Decrypt using an AES context (Requires !is_encryptor when initializing)
void DecryptBlock(const Aes128Context *ctx, void *dst, const void *src);

/// 128-bit CBC API.
void CbcContextCreate(Aes128CbcContext *out, const void *key, const void *iv, bool is_encryptor);

void CbcContextResetIv(Aes128CbcContext *ctx, const void *iv);

size_t CbcEncrypt(Aes128CbcContext *ctx, void *dst, const void *src, size_t size);

size_t CbcDecrypt(Aes128CbcContext *ctx, void *dst, const void *src, size_t size);

/// 128-bit CTR API.
void CtrContextCreate(Aes128CtrContext *out, const void *key, const void *ctr);

void CtrContextResetCtr(Aes128CtrContext *ctx, const void *ctr);

void CtrCrypt(Aes128CtrContext *ctx, void *dst, const void *src, size_t size);

/// 128-bit XTS API.
void XtsContextCreate(Aes128XtsContext *out, const void *key0, const void *key1, bool is_encryptor);

void XtsContextResetTweak(Aes128XtsContext *ctx, const void *tweak);

void XtsContextResetSector(Aes128XtsContext *ctx, uint64_t sector, bool is_nintendo);

size_t XtsEncrypt(Aes128XtsContext *ctx, void *dst, const void *src, size_t size);

size_t XtsDecrypt(Aes128XtsContext *ctx, void *dst, const void *src, size_t size);

} // namespace aes128

