/// @brief C++ wrappers for the `hipc` API.
/// @details Wraps: switch/sf/hipc.h.
namespace hipc {

using ::HipcBufferDescriptor;
using ::HipcBufferMode;
using ::HipcHeader;
using ::HipcMetadata;
using ::HipcParsedRequest;
using ::HipcRecvListEntry;
using ::HipcRequest;
using ::HipcResponse;
using ::HipcSpecialHeader;
using ::HipcStaticDescriptor;

HipcStaticDescriptor MakeSendStatic(const void* buffer, size_t size, u8 index);

HipcBufferDescriptor MakeBuffer(const void* buffer, size_t size, HipcBufferMode mode);

HipcRecvListEntry MakeRecvStatic(void* buffer, size_t size);

void* GetStaticAddress(const HipcStaticDescriptor* desc);

size_t GetStaticSize(const HipcStaticDescriptor* desc);

void* GetBufferAddress(const HipcBufferDescriptor* desc);

size_t GetBufferSize(const HipcBufferDescriptor* desc);

HipcRequest CalcRequestLayout(HipcMetadata meta, void* base);

HipcRequest MakeRequest(void* base, HipcMetadata meta);

HipcParsedRequest ParseRequest(void* base);

HipcResponse ParseResponse(void* base);

} // namespace hipc

/// @brief C++ wrappers for the `hmac` API.
/// @details Wraps: switch/crypto/hmac.h.
namespace hmac {

/// Context for HMAC-SHA1 operations.
using ::HmacSha1Context;
/// Context for HMAC-SHA256 operations.
using ::HmacSha256Context;

/// Initialize a HMAC-SHA256 context.
void Sha256ContextCreate(HmacSha256Context *out, const void *key, size_t key_size);

/// Updates HMAC-SHA256 context with data to hash
void Sha256ContextUpdate(HmacSha256Context *ctx, const void *src, size_t size);

/// Gets the context's output mac, finalizes the context.
void Sha256ContextGetMac(HmacSha256Context *ctx, void *dst);

/// Simple all-in-one HMAC-SHA256 calculator.
void Sha256CalculateMac(void *dst, const void *key, size_t key_size, const void *src, size_t size);

/// Initialize a HMAC-SHA1 context.
void Sha1ContextCreate(HmacSha1Context *out, const void *key, size_t key_size);

/// Updates HMAC-SHA1 context with data to hash
void Sha1ContextUpdate(HmacSha1Context *ctx, const void *src, size_t size);

/// Gets the context's output mac, finalizes the context.
void Sha1ContextGetMac(HmacSha1Context *ctx, void *dst);

/// Simple all-in-one HMAC-SHA1 calculator.
void Sha1CalculateMac(void *dst, const void *key, size_t key_size, const void *src, size_t size);

} // namespace hmac

/// @brief C++ wrappers for the `hosversion` API.
/// @details Wraps: switch/runtime/hosversion.h.
namespace hosversion {

/// Returns the current HOS version that was previously set with \ref hosversionSet. If version initialization fails during startup (such as in the case set:sys is not available), this function returns zero.
u32 Get(void);

/// Sets or overrides the current HOS version. This function is normally called automatically by libnx on startup with the version info obtained with \ref setsysGetFirmwareVersion.
void Set(u32 version);

/// Returns whether the current HOS version is augmented by running the AtmosphÃ¨re custom firmware.
bool IsAtmosphere(void);

/// Returns true if the current HOS version is equal to or above the specified major/minor/micro version.
bool AtLeast(u8 major, u8 minor, u8 micro);

/// Returns true if the current HOS version is earlier than the specified major/minor/micro version.
bool Before(u8 major, u8 minor, u8 micro);

/// Returns true if the current HOS version is between the two specified major versions, i.e. [major1, major2).
bool Between(u8 major1, u8 major2);

} // namespace hosversion

/// @brief C++ wrappers for the `hwopus` API.
/// @details Wraps: switch/services/hwopus.h.
namespace hwopus {

using ::HwopusDecoder;
/// This structure is the start of opusin for \ref hwopusDecodeInterleaved, with the actual opus packet following this.
/// These fields are big-endian.
using ::HwopusHeader;
/// Used internally.
using ::HwopusMultistreamState;

Result DecoderInitialize(HwopusDecoder* decoder, s32 SampleRate, s32 ChannelCount);

void DecoderExit(HwopusDecoder* decoder);

/// Only available on [3.0.0+].
/// See libopus multistream docs.
Result DecoderMultistreamInitialize(HwopusDecoder* decoder, s32 SampleRate, s32 ChannelCount, s32 TotalStreamCount, s32 StereoStreamCount, u8 *channel_mapping);

/// Decodes opus data.
Result DecodeInterleaved(HwopusDecoder* decoder, s32 *DecodedDataSize, s32 *DecodedSampleCount, const void* opusin, size_t opusin_size, s16 *pcmbuf, size_t pcmbuf_size);

} // namespace hwopus

