/**
 * @brief GetResult
 * @param r \ref NifmRequest
 */
Result GetResult(NifmRequest* r);

/**
 * @brief Cancel
 * @param r \ref NifmRequest
 */
Result RequestCancel(NifmRequest* r);

/**
 * @brief Submit
 * @param r \ref NifmRequest
 */
Result RequestSubmit(NifmRequest* r);

/**
 * @brief SubmitAndWait
 * @param r \ref NifmRequest
 */
