/// @brief C++ wrappers for the `romfs` API.
/// @details Wraps: switch/runtime/devices/romfs_dev.h.
namespace romfs {

/// RomFS directory.
using ::romfs_dir;
/// RomFS file.
using ::romfs_file;
/// RomFS header.
using ::romfs_header;

/**
 * @brief Mounts the Application's RomFS.
 * @param name Device mount name.
 * @remark This function is intended to be used to access one's own RomFS.
 *         If the application is running as NRO, it mounts the embedded RomFS section inside the NRO.
 *         If on the other hand it's an NSO, it behaves identically to \ref romfsMountFromCurrentProcess.
 */
Result MountSelf(const char *name);

/**
 * @brief Mounts RomFS from an open file.
 * @param file FsFile of the RomFS image.
 * @param offset Offset of the RomFS within the file.
 * @param name Device mount name.
 */
Result MountFromFile(FsFile file, u64 offset, const char *name);

/**
 * @brief Mounts RomFS from an open storage.
 * @param storage FsStorage of the RomFS image.
 * @param offset Offset of the RomFS within the storage.
 * @param name Device mount name.
 */
Result MountFromStorage(FsStorage storage, u64 offset, const char *name);

/**
 * @brief Mounts RomFS using the current process host program RomFS.
 * @param name Device mount name.
 */
Result MountFromCurrentProcess(const char *name);

/**
 * @brief Mounts RomFS of a running program.
 * @note Permission needs to be set in the NPDM.
 * @param program_id ProgramId to mount.
 * @param name Device mount name.
 */
Result MountDataStorageFromProgram(u64 program_id, const char *name);

/**
 * @brief Mounts RomFS from a file path in a mounted fsdev device.
 * @param path File path.
 * @param offset Offset of the RomFS within the file.
 * @param name Device mount name.
 */
Result MountFromFsdev(const char *path, u64 offset, const char *name);

/**
 * @brief Mounts RomFS from SystemData.
 * @param dataId SystemDataId to mount.
 * @param storageId Storage ID to mount from.
 * @param name Device mount name.
 */
Result MountFromDataArchive(u64 dataId, NcmStorageId storageId, const char *name);

/// Unmounts the RomFS device.
Result Unmount(const char *name);

/// Wrapper for \ref romfsMountSelf with the default "romfs" device name.
Result Init(void);

/// Wrapper for \ref romfsUnmount with the default "romfs" device name.
Result Exit(void);

} // namespace romfs

/// @brief C++ wrappers for the `rwlock` API.
/// @details Wraps: switch/kernel/rwlock.h.
namespace rwlock {

/// Read/write lock structure.
using ::RwLock;

/**
 * @brief Initializes the read/write lock.
 * @param r Read/write lock object.
 */
void Init(RwLock* r);

/**
 * @brief Locks the read/write lock for reading.
 * @param r Read/write lock object.
 */
void ReadLock(RwLock* r);

/**
 * @brief Attempts to lock the read/write lock for reading without waiting.
 * @param r Read/write lock object.
 * @return 1 if the mutex has been acquired successfully, and 0 on contention.
 */
bool TryReadLock(RwLock* r);

/**
 * @brief Unlocks the read/write lock for reading.
 * @param r Read/write lock object.
 */
void ReadUnlock(RwLock* r);

/**
 * @brief Locks the read/write lock for writing.
 * @param r Read/write lock object.
 */
void WriteLock(RwLock* r);

/**
 * @brief Attempts to lock the read/write lock for writing without waiting.
 * @param r Read/write lock object.
 * @return 1 if the mutex has been acquired successfully, and 0 on contention.
 */
bool TryWriteLock(RwLock* r);

/**
 * @brief Unlocks the read/write lock for writing.
 * @param r Read/write lock object.
 */
void WriteUnlock(RwLock* r);

/**
 * @brief Checks if the write lock is held by the current thread.
 * @param r Read/write lock object.
 * @return 1 if the current hold holds the write lock, and 0 if it does not.
 */
bool IsWriteLockHeldByCurrentThread(RwLock* r);

/**
 * @brief Checks if the read/write lock is owned by the current thread.
 * @param r Read/write lock object.
 * @return 1 if the current hold holds the write lock or if it holds read locks acquired
 *         while it held the write lock, and 0 if it does not.
 */
bool IsOwnedByCurrentThread(RwLock* r);

} // namespace rwlock

/// @brief C++ wrappers for the `semaphore` API.
/// @details Wraps: switch/kernel/semaphore.h.
namespace semaphore {

/// Semaphore structure.
using ::Semaphore;

/**
 * @brief Initializes a semaphore and its internal counter.
 * @param s Semaphore object.
 * @param initial_count initial value for internal counter (typically the # of free resources).
 */
void Init(Semaphore *s, u64 initial_count);

/**
 * @brief Increments the Semaphore to allow other threads to continue.
 * @param s Semaphore object.
 */
void Signal(Semaphore *s);

/**
 * @brief Decrements Semaphore and waits if 0.
 * @param s Semaphore object.
 */
void Wait(Semaphore *s);

/**
 * @brief Attempts to get lock without waiting.
 * @param s Semaphore object.
 * @return true if no wait and successful lock, false otherwise.
 */
bool TryWait(Semaphore *s);

} // namespace semaphore

/// @brief C++ wrappers for the `service` API.
/// @details Wraps: switch/sf/service.h.
namespace service {

/// Service object structure
using ::Service;
using ::SfBuffer;
using ::SfBufferAttrs;
using ::SfDispatchParams;
using ::SfOutHandleAttr;
using ::SfOutHandleAttrs;

/**
 * @brief Returns whether a service has been initialized.
 * @param[in] s Service object.
 * @return true if initialized.
 */
bool IsActive(Service* s);

/**
 * @brief Returns whether a service is overriden in the homebrew environment.
 * @param[in] s Service object.
 * @return true if overriden.
 */
bool IsOverride(Service* s);

/**
 * @brief Returns whether a service is a domain.
 * @param[in] s Service object.
 * @return true if a domain.
 */
bool IsDomain(Service* s);

/**
 * @brief Returns whether a service is a domain subservice.
 * @param[in] s Service object.
 * @return true if a domain subservice.
 */
bool IsDomainSubservice(Service* s);

/**
 * @brief For a domain/domain subservice, return the associated object ID.
 * @param[in] s Service object, necessarily a domain or domain subservice.
 * @return The object ID.
 */
u32 GetObjectId(Service* s);

/**
 * @brief Creates a service object from an IPC session handle.
 * @param[out] s Service object.
 * @param[in] h IPC session handle.
 */
void Create(Service* s, Handle h);

/**
 * @brief Creates a non-domain subservice object from a parent service.
 * @param[out] s Service object.
 * @param[in] parent Parent service.
 * @param[in] h IPC session handle for this subservice.
 */
void CreateNonDomainSubservice(Service* s, Service* parent, Handle h);

/**
 * @brief Creates a domain subservice object from a parent service.
 * @param[out] s Service object.
 * @param[in] parent Parent service, necessarily a domain or domain subservice.
 * @param[in] object_id Object ID for this subservice.
 */
void CreateDomainSubservice(Service* s, Service* parent, u32 object_id);

/**
 * @brief Closes a service.
 * @param[in] s Service object.
 */
void Close(Service* s);

/**
 * @brief Clones a service.
 * @param[in] s Service object.
 * @param[out] out_s Output service object.
 */
Result Clone(Service* s, Service* out_s);

/**
 * @brief Clones a service with a session manager tag.
 * @param[in] s Service object.
 * @param[in] tag Session manager tag (unused in current official server code)
 * @param[out] out_s Output service object.
 */
Result CloneEx(Service* s, u32 tag, Service* out_s);

/**
 * @brief Converts a regular service to a domain.
 * @param[in] s Service object.
 * @return Result code.
 */
Result ConvertToDomain(Service* s);

void RequestFormatProcessBuffer(CmifRequestFormat* fmt, u32 attr);

void RequestProcessBuffer(CmifRequest* req, const SfBuffer* buf, u32 attr);

void* MakeRequest(Service* s, u32 request_id, u32 context, u32 data_size, bool send_pid, const SfBufferAttrs buffer_attrs, const SfBuffer* buffers, u32 num_objects, const Service* const* objects, u32 num_handles, const Handle* handles);

void ResponseGetHandle(CmifResponse* res, SfOutHandleAttr type, Handle* out);

Result ParseResponse(Service* s, u32 out_size, void** out_data, u32 num_out_objects, Service* out_objects, const SfOutHandleAttrs out_handle_attrs, Handle* out_handles);

Result DispatchImpl(Service* s, u32 request_id, const void* in_data, u32 in_data_size, void* out_data, u32 out_data_size, SfDispatchParams disp);

} // namespace service

