/// @brief C++ wrappers for the `sha1` API.
/// @details Wraps: switch/crypto/sha1.h.
namespace sha1 {

/// Context for SHA1 operations.
using ::Sha1Context;

/// Initialize a SHA1 context.
void ContextCreate(Sha1Context *out);

/// Updates SHA1 context with data to hash
void ContextUpdate(Sha1Context *ctx, const void *src, size_t size);

/// Gets the context's output hash, finalizes the context.
void ContextGetHash(Sha1Context *ctx, void *dst);

/// Simple all-in-one SHA1 calculator.
void CalculateHash(void *dst, const void *src, size_t size);

} // namespace sha1

/// @brief C++ wrappers for the `sha256` API.
/// @details Wraps: switch/crypto/sha256.h.
namespace sha256 {

/// Context for SHA256 operations.
using ::Sha256Context;

/// Initialize a SHA256 context.
void ContextCreate(Sha256Context *out);

/// Updates SHA256 context with data to hash
void ContextUpdate(Sha256Context *ctx, const void *src, size_t size);

/// Gets the context's output hash, finalizes the context.
void ContextGetHash(Sha256Context *ctx, void *dst);

/// Simple all-in-one SHA256 calculator.
void CalculateHash(void *dst, const void *src, size_t size);

} // namespace sha256

/// @brief C++ wrappers for the `shmem` API.
/// @details Wraps: switch/kernel/shmem.h.
namespace shmem {

/// Shared memory information structure.
using ::SharedMemory;

/**
 * @brief Creates a shared memory object.
 * @param s Shared memory information structure which will be filled in.
 * @param size Size of the shared memory object to create.
 * @param local_perm Permissions with which the shared memory object will be mapped in the local process.
 * @param remote_perm Permissions with which the shared memory object will be mapped in the remote process (can be Perm_DontCare).
 * @return Result code.
 * @warning This is a privileged operation; in normal circumstances applications cannot use this function.
 */
Result Create(SharedMemory* s, size_t size, Permission local_perm, Permission remote_perm);

/**
 * @brief Loads a shared memory object coming from a remote process.
 * @param s Shared memory information structure which will be filled in.
 * @param handle Handle of the shared memory object.
 * @param size Size of the shared memory object that is being loaded.
 * @param perm Permissions with which the shared memory object will be mapped in the local process.
 */
void LoadRemote(SharedMemory* s, Handle handle, size_t size, Permission perm);

/**
 * @brief Maps a shared memory object.
 * @param s Shared memory information structure.
 * @return Result code.
 */
Result Map(SharedMemory* s);

/**
 * @brief Unmaps a shared memory object.
 * @param s Shared memory information structure.
 * @return Result code.
 */
Result Unmap(SharedMemory* s);

/**
 * @brief Retrieves the mapped address of a shared memory object.
 * @param s Shared memory information structure.
 * @return Mapped address of the shared memory object.
 */
void* GetAddr(SharedMemory* s);

/**
 * @brief Frees up resources used by a shared memory object, unmapping and closing handles, etc.
 * @param s Shared memory information structure.
 * @return Result code.
 */
Result Close(SharedMemory* s);

} // namespace shmem

/// @brief C++ wrappers for the `sm` API.
/// @details Wraps: switch/services/sm.h, switch/services/smm.h.
namespace sm {

/// Structure representing a service name (null terminated, remaining characters set to zero).
using ::SmServiceName;

/// Converts a service name into a 64-bit integer.
u64 ServiceNameToU64(SmServiceName name);

/// Converts a 64-bit integer into a service name.
SmServiceName ServiceNameFromU64(u64 name);

/**
 * @brief Checks whether two service names are equal.
 * @param[in] a First name.
 * @param[in] b Second name.
 * @return Comparison result.
 */
bool ServiceNamesAreEqual(SmServiceName a, SmServiceName b);

/**
 * @brief Encodes a service name string as a \ref SmServiceName structure.
 * @param[in] name Name of the service.
 * @return Encoded name.
 */
SmServiceName EncodeName(const char* name);

/**
 * @brief Initializes SM.
 * @return Result code.
 * @note This function is already called in the default application startup code (before main() is called).
 */
Result Initialize(void);

/**
 * @brief Uninitializes SM.
 * @return Result code.
 * @note This function is already handled in the default application exit code (after main() returns).
 */
void Exit(void);

/**
 * @brief Requests a service from SM, allowing overrides.
 * @param[out] service_out Service structure which will be filled in.
 * @param[in] name Name of the service to request.
 * @return Result code.
 */
Result GetServiceWrapper(Service* service_out, SmServiceName name);

/**
 * @brief Requests a service from SM, as an IPC session handle directly
 * @param[out] handle_out Variable containing IPC session handle.
 * @param[in] name Name of the service to request.
 * @return Result code.
 */
Result GetServiceOriginal(Handle* handle_out, SmServiceName name);

/**
 * @brief Requests a service from SM.
 * @param[out] service_out Service structure which will be filled in.
 * @param[in] name Name of the service to request (as a string).
 * @return Result code.
 */
Result GetService(Service* service_out, const char* name);

/**
 * @brief Retrieves an overriden service in the homebrew environment.
 * @param[in] name Name of the service to request.
 * @return IPC session handle.
 */
Handle GetServiceOverride(SmServiceName name);

/**
 * @brief Creates and registers a new service within SM.
 * @param[out] handle_out Variable containing IPC port handle.
 * @param[in] name Name of the service.
 * @param[in] is_light "Is light"
 * @param[in] max_sessions Maximum number of concurrent sessions that the service will accept.
 * @return Result code.
 */
Result RegisterService(Handle* handle_out, SmServiceName name, bool is_light, s32 max_sessions);

/// Same as \ref smRegisterService, but always using cmif serialization.
Result RegisterServiceCmif(Handle* handle_out, SmServiceName name, bool is_light, s32 max_sessions);

/// Same as \ref smRegisterService, but always using tipc serialization.
Result RegisterServiceTipc(Handle* handle_out, SmServiceName name, bool is_light, s32 max_sessions);

/**
 * @brief Unregisters a previously registered service in SM.
 * @param[in] name Name of the service.
 * @return Result code.
 */
Result UnregisterService(SmServiceName name);

/// Same as \ref smUnregisterService, but always using cmif serialization.
Result UnregisterServiceCmif(SmServiceName name);

/// Same as \ref smUnregisterService, but always using tipc serialization.
Result UnregisterServiceTipc(SmServiceName name);

/**
 * @brief Detaches the current SM session.
 * @note After this function is called, the rest of the SM API cannot be used.
 * @note Only available on [11.0.0-11.0.1], or AtmosphÃ¨re.
 */
Result DetachClient(void);

/// Same as \ref smDetachClient, but always using cmif serialization.
Result DetachClientCmif(void);

/// Same as \ref smDetachClient, but always using tipc serialization.
Result DetachClientTipc(void);

/**
 * @brief Gets the Service session used to communicate with SM.
 * @return Pointer to service session used to communicate with SM.
 */
Service * GetServiceSession(void);

/**
 * @brief Gets the TipcService session used to communicate with SM.
 * @return Pointer to tipc service session used to communicate with SM.
 * @note Only available on [12.0.0+], or AtmosphÃ¨re.
 */
TipcService * GetServiceSessionTipc(void);

/**
 * @brief Overrides a service with a custom IPC service handle.
 * @param[in] name Name of the service.
 * @param[in] handle IPC session handle.
 */
void AddOverrideHandle(SmServiceName name, Handle handle);

/// Initialize sm:m.
Result ManagerInitialize(void);

/// Exit sm:m.
void ManagerExit(void);

Result ManagerRegisterProcess(u64 pid, const void *acid_sac, size_t acid_sac_size, const void *aci0_sac, size_t aci0_sac_size);

Result ManagerUnregisterProcess(u64 pid);

/// Initialize sm:m exclusively for tipc (requires <12.0.0 and non-Atmosphere).
Result ManagerCmifInitialize(void);

/// Exit sm:m exclusively for tipc (requires <12.0.0 and non-Atmosphere).
void ManagerCmifExit(void);

/// Gets the Service object for the actual sm:m service session (requires <12.0.0 and non-Atmosphere).
Service* ManagerCmifGetServiceSession(void);

Result ManagerCmifRegisterProcess(u64 pid, const void *acid_sac, size_t acid_sac_size, const void *aci0_sac, size_t aci0_sac_size);

Result ManagerCmifUnregisterProcess(u64 pid);

/// Initialize sm:m exclusively for tipc (requires 12.0.0+ or Atmosphere).
Result ManagerTipcInitialize(void);

/// Exit sm:m exclusively for tipc (requires 12.0.0+ or Atmosphere).
void ManagerTipcExit(void);

/// Gets the TipcService object for the actual sm:m service session (requires 12.0.0+ or Atmosphere).
TipcService* ManagerTipcGetServiceSession(void);

Result ManagerTipcRegisterProcess(u64 pid, const void *acid_sac, size_t acid_sac_size, const void *aci0_sac, size_t aci0_sac_size);

Result ManagerTipcUnregisterProcess(u64 pid);

} // namespace sm

/// @brief C++ wrappers for the `socket` API.
/// @details Wraps: switch/runtime/devices/socket.h.
namespace socket {

/// BSD service type used by the socket driver.
using ::BsdServiceType;
#ifdef _SOCKLEN_T_DECLARED
using ::sockaddr;
#endif
/// Configuration structure for socketInitalize
using ::SocketInitConfig;

/// Fetch the default configuration for the socket driver.
const SocketInitConfig * GetDefaultInitConfig(void);

/// Initalize the socket driver.
Result Initialize(const SocketInitConfig *config);

/// Fetch the last bsd:u/s Switch result code (thread-local).
Result GetLastResult(void);

/// Deinitialize the socket driver.
void Exit(void);

/// Initalize the socket driver using the default configuration.
Result InitializeDefault(void);

/// Wrapper for \ref sslConnectionSetSocketDescriptor. Returns the output sockfd on success and -1 on error. errno==ENOENT indicates that no sockfd was returned, this error must be ignored.
int SslConnectionSetSocketDescriptor(SslConnection *c, int sockfd);

/// Wrapper for \ref sslConnectionGetSocketDescriptor. Returns the output sockfd on success and -1 on error.
int SslConnectionGetSocketDescriptor(SslConnection *c);

#ifdef _SOCKLEN_T_DECLARED
/// Wrapper for \ref sslConnectionSetDtlsSocketDescriptor. Returns the output sockfd on success and -1 on error. errno==ENOENT indicates that no sockfd was returned, this error must be ignored.
int SslConnectionSetDtlsSocketDescriptor(SslConnection *c, int sockfd, const struct sockaddr *addr, socklen_t addrlen);
#endif

/// Wrapper for \ref nifmRequestRegisterSocketDescriptor. Returns 0 on success and -1 on error.
int NifmRequestRegisterSocketDescriptor(NifmRequest* r, int sockfd);

/// Wrapper for \ref nifmRequestUnregisterSocketDescriptor. Returns 0 on success and -1 on error.
int NifmRequestUnregisterSocketDescriptor(NifmRequest* r, int sockfd);

} // namespace socket

